<div class="page-head"><div><h1><?=e($title)?></h1><p>Acompanhe todos os turnos confirmados e concluídos.</p></div></div><section class="panel"><div class="table-wrap"><table class="tp-table"><thead><tr><th>Data</th><th>Função</th><th>Empresa</th><th>Horário</th><th>Valor</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($assignments as $a):?><tr><td><?=br_date($a['starts_at'])?></td><td><strong><?=e($a['category_name'])?></strong></td><td><?=e($a['company_name'])?></td><td><?=date('H:i',strtotime($a['starts_at']))?> – <?=date('H:i',strtotime($a['ends_at']))?></td><td><strong><?=money($a['agreed_value'])?></strong></td><td><span class="status <?=$a['status']==='completed'?'published':'filling'?>"><?=e(ucfirst(str_replace('_',' ',$a['status'])))?></span></td><td><a class="btn btn-soft btn-sm" href="<?=e(url('profissional/turno/'.$a['id']))?>">Abrir turno</a></td></tr><?php endforeach;?></tbody></table></div></section>
